Create a new plugin file with any name and import it as a plugin. Paste this:
Code:
(function() {
function condition() {
    return !(SceneManager._scene instanceof Scene_Map && $gameSwitches.value(1)) // <--
}
const _isPressed = TouchInput.isPressed;
TouchInput.isPressed = function() {
    return condition() && _isPressed.call(this);
}
const _isTriggered = TouchInput.isTriggered;
TouchInput.isTriggered = function() {
    return condition() && _isTriggered.call(this);
}
const _isRepeated = TouchInput.isRepeated;
TouchInput.isRepeated = function() {
    return condition() && _isRepeated.call(this);
}
const _isLongPressed = TouchInput.isLongPressed;
TouchInput.isLongPressed = function() {
    return condition() && _isLongPressed.call(this);
}
const _isReleased = TouchInput.isReleased;
TouchInput.isReleased = function() {
    return condition() && _isReleased.call(this);
}
})()
Replace the 1 with a Switch ID of your choice. Once the Switch is ON, all Touch Inputs are ignored.

